fn prime_num(n: u64) -> bool {
    // Requires that n is a non-negative integer
    // Ensures that the return value is true if n is prime, false otherwise
    // The function assumes n is at least 2 for the prime check
    // Invariant: n >= 0
    // Decreases: n (as we are checking divisors up to sqrt(n))
    requires(n >= 0);
    ensures((result == true) == (is_prime(n)));
    
    if n < 2 {
        return false; // Since we assume n is at least 2, this is just a safety check.
    }
    if n == 2 {
        return true; // 2 is the only even prime number.
    }
    if n % 2 == 0 {
        return false; // Exclude all other even numbers.
    }
    
    let limit = (n as f64).sqrt() as u64; // Calculate the square root of n.
    // Invariant: 3 <= k <= limit
    for k in 3..=limit {
        // Invariant: n % k == 0 implies n is not prime
        if n % k == 0 {
            return false; // Found a divisor, so n is not prime.
        }
    }
    
    true // No divisors found, n is prime.
}

// Helper function to determine if a number is prime
// This function is used for the ensures clause in prime_num
fn is_prime(n: u64) -> bool {
    if n < 2 {
        return false;
    }
    if n == 2 {
        return true;
    }
    if n % 2 == 0 {
        return false;
    }
    let limit = (n as f64).sqrt() as u64;
    for k in 3..=limit {
        if n % k == 0 {
            return false;
        }
    }
    true
}

